import{a as t,p as c,e as d,f as v}from"./index-CGqdfrTO.js";const f={},b={class:"help-page"};function s(o,a){return c(),d("div",b,[...a[0]||(a[0]=[v('<div class="container" data-v-6b664c3f><h1 data-v-6b664c3f>帮助文档</h1><p class="subtitle" data-v-6b664c3f>拼豆图纸生成器使用指南</p><div class="help-sections" data-v-6b664c3f><section class="card help-section" data-v-6b664c3f><h2 data-v-6b664c3f>快速入门</h2><ol class="steps-list" data-v-6b664c3f><li data-v-6b664c3f><strong data-v-6b664c3f>上传图片</strong><p data-v-6b664c3f>在&quot;工作台&quot;页面，点击上传区域或拖拽图片文件到页面中。支持 JPG、PNG、WebP、BMP 等常见格式。</p></li><li data-v-6b664c3f><strong data-v-6b664c3f>设置像素尺寸</strong><p data-v-6b664c3f>设置目标图纸的宽度和高度（拼豆数量）。数值越大图纸越精细，但也需要更多的拼豆。可以使用快速预设或手动输入数值。</p></li><li data-v-6b664c3f><strong data-v-6b664c3f>选择品牌色盘</strong><p data-v-6b664c3f>选择您使用的拼豆品牌（Perler、Artkal 或 Hama），系统会自动将图片颜色匹配到该品牌最接近的色号。</p></li><li data-v-6b664c3f><strong data-v-6b664c3f>预览与微调</strong><p data-v-6b664c3f>查看匹配结果，点击像素点可手动调整颜色选择。确认满意后进入导出步骤。</p></li><li data-v-6b664c3f><strong data-v-6b664c3f>导出图纸</strong><p data-v-6b664c3f>选择导出 PNG 图片图纸或 PDF 文档（包含材料清单）。PDF 格式适合打印后对照制作。</p></li></ol></section><section class="card help-section" data-v-6b664c3f><h2 data-v-6b664c3f>AI 图像增强功能</h2><p data-v-6b664c3f>本工具内置 AI 图像处理能力，包括：</p><ul data-v-6b664c3f><li data-v-6b664c3f><strong data-v-6b664c3f>像素化处理：</strong>将普通图片转换为马赛克风格，适配拼豆像素化需求。</li><li data-v-6b664c3f><strong data-v-6b664c3f>边缘平滑滤波：</strong>在像素化处理后自动进行噪声过滤，减少色彩噪点。</li><li data-v-6b664c3f><strong data-v-6b664c3f>颜色量化：</strong>使用中位切分算法优化色彩分布，使匹配后的图案更加自然。</li></ul><p data-v-6b664c3f>您可以在&quot;像素化设置&quot;步骤中调整 AI 增强强度参数。</p></section><section class="card help-section" data-v-6b664c3f><h2 data-v-6b664c3f>颜色匹配算法</h2><p data-v-6b664c3f>系统使用加权欧几里得距离算法进行颜色匹配，权重参考人眼对不同颜色通道的敏感度（红色 2-3x、绿色 4x、蓝色 2-3x），确保匹配结果更符合人眼视觉感知。</p><p data-v-6b664c3f>匹配过程采用内存缓存优化，大幅提升处理速度。</p></section><section class="card help-section" data-v-6b664c3f><h2 data-v-6b664c3f>拼豆品牌色盘</h2><table class="brand-table" data-v-6b664c3f><thead data-v-6b664c3f><tr data-v-6b664c3f><th data-v-6b664c3f>品牌</th><th data-v-6b664c3f>色号前缀</th><th data-v-6b664c3f>颜色数量</th><th data-v-6b664c3f>说明</th></tr></thead><tbody data-v-6b664c3f><tr data-v-6b664c3f><td data-v-6b664c3f>Perler</td><td data-v-6b664c3f><code data-v-6b664c3f>Pxx</code></td><td data-v-6b664c3f>50色</td><td data-v-6b664c3f>最常见的拼豆品牌，颜色丰富</td></tr><tr data-v-6b664c3f><td data-v-6b664c3f>Artkal</td><td data-v-6b664c3f><code data-v-6b664c3f>Axx</code></td><td data-v-6b664c3f>50色</td><td data-v-6b664c3f>国内常用品牌，与Perler兼容</td></tr><tr data-v-6b664c3f><td data-v-6b664c3f>Hama</td><td data-v-6b664c3f><code data-v-6b664c3f>Hxx</code></td><td data-v-6b664c3f>50色</td><td data-v-6b664c3f>欧洲主流品牌，色系更柔和</td></tr></tbody></table></section><section class="card help-section" data-v-6b664c3f><h2 data-v-6b664c3f>导出格式说明</h2><ul data-v-6b664c3f><li data-v-6b664c3f><strong data-v-6b664c3f>PNG 图纸：</strong>带网格线和色号标记的高清图，适合屏幕查看和标记。</li><li data-v-6b664c3f><strong data-v-6b664c3f>PDF 文档：</strong>A4格式，包含图纸页和材料清单页，适合打印。</li><li data-v-6b664c3f><strong data-v-6b664c3f>材料清单(TXT)：</strong>纯文本格式的材料消耗清单。</li><li data-v-6b664c3f><strong data-v-6b664c3f>材料清单(CSV)：</strong>可用Excel/WPS打开的表格格式。</li><li data-v-6b664c3f><strong data-v-6b664c3f>购物清单：</strong>复制到剪贴板，可直接粘贴到记事本或购物应用中使用。</li></ul></section><section class="card help-section" data-v-6b664c3f><h2 data-v-6b664c3f>常见问题</h2><div class="faq-item" data-v-6b664c3f><h4 data-v-6b664c3f>Q: 图片应该选多大尺寸？</h4><p data-v-6b664c3f>A: 建议设置 29x29（小板）、48x48（中板）或 58x58（大板）。更大尺寸需要更多拼豆。</p></div><div class="faq-item" data-v-6b664c3f><h4 data-v-6b664c3f>Q: 为什么匹配结果有色差？</h4><p data-v-6b664c3f>A: 实体拼豆颜色有限，算法会匹配最接近的颜色。您可以使用手动微调功能调整不理想的匹配。</p></div><div class="faq-item" data-v-6b664c3f><h4 data-v-6b664c3f>Q: 数据保存在哪里？</h4><p data-v-6b664c3f>A: 所有项目数据保存在浏览器的本地存储中。清除浏览器数据会导致项目丢失，请及时导出重要项目。</p></div></section></div></div>',1)])])}const l=t(f,[["render",s],["__scopeId","data-v-6b664c3f"]]);export{l as default};
